@import '../../utils/interaction-fill.css';
@import '../../utils/focus-ring.css';
@import '../../utils/control-density.css';
@import '../../utils/control-parts.css';
@import '../../styles/control-elevation.css';

/* The summary bar follows the theme-reactive inverted sub-theme. */

:host {
  display: block;
  box-sizing: border-box;
  /* Drives the narrow layout below from the card's own width, not the viewport's. */
  container-type: inline-size;
  /* A summary is read, not copied; stray selection while clicking cells is noise. */
  -webkit-user-select: none;
  user-select: none;
  /* Width a metric may shrink to before the grid drops a column. */
  --ds-card-overview-metric-min: calc(var(--dimension-size-400) * 5);
  --ds-card-overview-divider-width: var(--dimension-stroke-width-012);
  --ds-card-overview-divider-color: var(--color-inverted-border-tertiary);
  --ds-card-overview-divider: var(--ds-card-overview-divider-width) solid
    var(--ds-card-overview-divider-color);
  color: var(--color-inverted-foreground-primary);
}

.card-overview__surface {
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
  border-radius: var(--dimension-radius-050);
  background: var(--color-inverted-background);
  color: var(--color-inverted-foreground-primary);
  overflow-anchor: none;
}

/*
 * The visual surface owns elevation outside this clipping viewport. Keeping
 * those layers separate lets a page shrink the surface while content moves and
 * clips inside it without cutting off the shadow or inset highlight.
 */
.card-overview__clip {
  height: 100%;
  min-width: 0;
  border-radius: inherit;
  background: inherit;
  overflow: hidden;
}

:host(.card-overview--scroll-collapsing) {
  height: var(--ds-card-overview-expanded-height);
  pointer-events: none;
}

:host(.card-overview--scroll-collapsing) .card-overview__surface {
  height: var(--ds-card-overview-visible-height);
  pointer-events: auto;
  will-change: height;
}

:host(.card-overview--scroll-collapsing) .card-overview__layout {
  transform: translateY(calc(-1 * var(--ds-card-overview-content-offset)));
  will-change: transform;
}

.card-overview__layout {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-columns: minmax(0, 1fr);
  align-items: stretch;
  min-width: 0;
}

.card-overview__layout--has-score {
  grid-template-columns: auto minmax(0, 1fr);
}

/*
 * Transparent at regular widths so the score and header participate in the
 * inner layout grid directly. At the narrow breakpoint it becomes the unified
 * summary block above the metrics.
 */
.card-overview__summary {
  display: contents;
}

/* ── Score ────────────────────────────────────────────────────────────────── */

/*
 * Hugs its content and never shrinks, so the headline figure keeps its size and
 * the metric grid absorbs the remaining width.
 */
/*
 * Top aligned rather than centred, and padded to match the header, so the score
 * label sits in the same 32px box at the same offset as the period text beside
 * it. Both use the same type variant, so their baselines land together.
 */
.card-overview__score {
  display: flex;
  grid-row: 1 / span 2;
  grid-column: 1;
  flex: 0 0 auto;
  flex-direction: column;
  gap: 0;
  min-width: 0;
  padding: var(--dimension-space-100) var(--dimension-space-200);
  border-inline-end: var(--ds-card-overview-divider);
}

.card-overview__score--resolved {
  min-inline-size: max-content;
}

/* The control-height box that aligns this label with the period text. */
.card-overview__score-label-row {
  display: flex;
  align-items: center;
  min-height: var(--ds-control-height);
}

/*
 * The score is its own column, so its rows cannot baseline-align with the measure
 * rows through flex or grid — those only align items that share a line. These two
 * offsets pull the column onto the measure baselines instead.
 *
 * They are compensation for how much lower a display-scale figure sits in its line
 * box than the body text it aligns to, so they are coupled to the type pairing:
 * change the score or measure variants and both need re-measuring.
 */
.card-overview__score-figure {
  display: flex;
  align-items: baseline;
  gap: var(--dimension-space-050);
  min-width: 0;
  margin-block-start: calc(-1 * (var(--dimension-space-150) + var(--dimension-space-012)));
}

.card-overview__score-value {
  flex: 0 0 auto;
}

/* Second half of the baseline compensation described above the score figure. */
.card-overview__score-band {
  margin-block-start: calc(-1 * var(--dimension-space-025));
}

/*
 * A skeleton bar is a solid block, so in a baseline-aligned row it aligns on its
 * bottom edge while the text it stands in for aligns on its baseline. Next to a
 * display-scale figure that difference is the descent under the figure's
 * baseline, which drops the bar below where the resolved trend sits.
 *
 * The offset is applied with relative positioning rather than a margin: a margin
 * is not part of a synthesized baseline, so it grows the figure instead of moving
 * the bar, which then pushes the band below it out of place.
 *
 * Only needed beside the score figure; the measure rows pair body variants whose
 * bottom edge and baseline already agree.
 */
.card-overview__skeleton-baseline {
  position: relative;
  inset-block-start: calc(-1 * var(--dimension-space-150));
}

.card-overview__score--error {
  flex-direction: row;
  align-items: center;
  gap: var(--dimension-space-050);
  color: var(--color-inverted-foreground-negative);
}

/* ── Body ─────────────────────────────────────────────────────────────────── */

/*
 * Takes the remaining inline space. The minimum is what makes the host wrap: once
 * the score and roughly two measure columns no longer fit side by side, the body
 * drops below the score instead of squeezing it. `min()` keeps that from becoming
 * an overflow floor on very narrow viewports.
 */
.card-overview__body {
  display: flex;
  grid-row: 2;
  grid-column: 1;
  flex-direction: column;
  min-width: 0;
}

.card-overview__body--has-score {
  grid-column: 2;
}

/*
 * One control row: 8px of padding on every side around a 32px md control, so the
 * bar is 8 + 32 + 8. Both ends of the bar are control-shaped boxes — the period
 * text on the left and the slotted control on the right — so the row reads
 * balanced rather than text on one side and a control on the other.
 */
.card-overview__header {
  display: flex;
  grid-row: 1;
  grid-column: 1;
  align-items: center;
  gap: var(--dimension-space-100);
  min-width: 0;
  padding: var(--dimension-space-100);
  border-block-end: var(--ds-card-overview-divider);
  box-sizing: border-box;
}

.card-overview__header--has-score {
  grid-column: 2;
}

/*
 * Matches the control's box on the opposite end, including its inline padding, so
 * the text lands at the same optical inset the slotted control does:
 * 8 from the bar + 6 from this box + 2 from the label inset = 16.
 *
 * Nowrap keeps the row at the control height; the period truncates rather than
 * growing the bar to two lines.
 */
.card-overview__period {
  display: flex;
  flex: 1 1 auto;
  align-items: center;
  gap: var(--dimension-space-050);
  min-height: var(--ds-control-height);
  min-width: 0;
  padding-inline: var(--ds-control-padding-inline);
  overflow: hidden;
  white-space: nowrap;
}

/* The period control is slotted, so only reserve space for it. */
.card-overview__filter {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
}

/* ── Metrics ──────────────────────────────────────────────────────────────── */

/*
 * `auto-fit` gives every occupied track an equal share while all metrics fit on
 * one row. Once wrapping creates another row, its cells stay on those same
 * tracks, so a partial final row leaves empty space instead of stretching one
 * measure wider than its peers.
 *
 * Dividers are painted outward from each cell and clipped by this grid. That
 * leaves only the lines between cells: anything emitted from the final column or
 * final row lands outside the grid and is clipped without needing to detect the
 * number of tracks.
 *
 * `flex: 1 1 auto` makes the grid absorb whatever height the body has
 * left, so cells reach the card bottom and their hover wash has no dead strip.
 */
.card-overview__metrics {
  display: grid;
  flex: 1 1 auto;
  grid-template-columns: repeat(
    auto-fit,
    minmax(min(100%, var(--ds-card-overview-metric-min)), 1fr)
  );
  align-content: stretch;
  min-width: 0;
  overflow: clip;
}

/*
 * Square by design. Cells tile edge to edge against their dividers, so a radius
 * would break the seam; the card's own radius clips the outer corners instead.
 *
 * Padding is plain rather than control-derived: a cell is a block of content, not
 * a control box that has to optically match something on the far side.
 */
.card-overview__metric {
  display: flex;
  position: relative;
  flex-direction: column;
  gap: var(--dimension-space-050);
  min-width: 0;
  padding: var(--dimension-space-175) var(--dimension-space-200);
  border-radius: 0;
  box-shadow:
    var(--ds-card-overview-divider-width) 0 0 0 var(--ds-card-overview-divider-color),
    0 var(--ds-card-overview-divider-width) 0 0 var(--ds-card-overview-divider-color);
}

.card-overview__metric[role='button'] {
  cursor: default;
  -webkit-user-select: none;
  user-select: none;
}

.card-overview__metric-label {
  min-width: 0;
}

.card-overview__metric-figure {
  display: flex;
  align-items: baseline;
  gap: var(--dimension-space-100);
  min-width: 0;
}

/* ── Trend ────────────────────────────────────────────────────────────────── */

/*
 * Tone arrives resolved from the caller: the arrow direction and the sentiment
 * are independent, so a falling metric can read positive or neutral. The arrow is
 * a glyph inside this text node, so it always matches the surrounding weight.
 */
.card-overview__trend {
  flex: 0 0 auto;
  white-space: nowrap;
}

/* ── Narrow layout ────────────────────────────────────────────────────────── */

/*
 * Below roughly two measure columns the card becomes a full stack. The summary
 * wrapper owns one block above the metrics: score label, figure, and trend stay
 * together at the start; the period control sits at the upper end; and the period
 * copy follows the score instead of becoming a separate divided row.
 */
/*
 * Selectors are host-qualified purely for specificity: the compiled sheet places
 * these rules ahead of the base ones, so a plain class here would only ever add
 * properties and never override them.
 */
@container (max-width: 480px) {
  :host .card-overview__layout {
    grid-template-rows: auto minmax(0, 1fr);
    grid-template-columns: minmax(0, 1fr);
  }

  :host .card-overview__summary {
    display: grid;
    grid-row: 1;
    grid-column: 1;
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-rows: auto;
    border-block-end: var(--ds-card-overview-divider);
  }

  :host .card-overview__score {
    display: grid;
    grid-row: 1;
    grid-column: 1;
    grid-template-rows: auto auto;
    grid-template-columns: auto auto;
    justify-content: start;
    column-gap: var(--dimension-space-100);
    width: auto;
    padding-block-end: var(--dimension-space-100);
    padding-inline-end: var(--dimension-space-100);
    border-inline-end: none;
  }

  :host .card-overview__score-label-row {
    grid-row: 1;
    grid-column: 1 / -1;
    min-height: var(--ds-control-height);
  }

  /*
   * The wide score uses optical offsets to meet the neighbouring metric
   * baselines. In the stacked summary those neighbours are gone, so natural
   * document flow keeps the label, figure, band, and period clearly ordered.
   */
  :host .card-overview__score-band,
  :host .card-overview__score-figure {
    grid-row: 2;
    margin-block-start: 0;
  }

  :host .card-overview__score-figure {
    grid-column: 1;
    align-self: baseline;
    gap: var(--dimension-space-100);
  }

  :host .card-overview__score-band {
    grid-column: 2;
    align-self: baseline;
    display: none;
  }

  :host .card-overview__header {
    display: grid;
    grid-row: 1;
    grid-column: 2;
    grid-template-rows: auto auto;
    align-content: start;
    gap: 0;
    padding: 0;
    border-block-end: none;
  }

  :host .card-overview__filter {
    grid-row: 1;
    grid-column: 1;
    align-self: start;
    justify-self: end;
    padding: var(--dimension-space-100) var(--dimension-space-100) 0 0;
  }

  :host .card-overview__period {
    grid-row: 2;
    grid-column: 1;
    flex-direction: column;
    align-items: flex-end;
    justify-self: stretch;
    gap: 0;
    min-height: 0;
    padding-block: var(--dimension-space-150) var(--dimension-space-100);
    padding-inline: var(--dimension-space-100) var(--dimension-space-200);
    overflow: visible;
    text-align: end;
    white-space: nowrap;
  }

  :host .card-overview__body {
    grid-row: 2;
    grid-column: 1;
  }
}

/*
 * Page shells may enter a responsive mode before this card itself becomes
 * narrow. The explicit stacked layout applies the same composition without
 * coupling CardOverview to a viewport breakpoint.
 */
:host(.card-overview--stacked) .card-overview__layout {
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-columns: minmax(0, 1fr);
}

:host(.card-overview--stacked) .card-overview__summary {
  display: grid;
  grid-row: 1;
  grid-column: 1;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto;
  border-block-end: var(--ds-card-overview-divider);
}

:host(.card-overview--stacked) .card-overview__score {
  display: grid;
  grid-row: 1;
  grid-column: 1;
  grid-template-rows: auto auto;
  grid-template-columns: auto auto;
  justify-content: start;
  column-gap: var(--dimension-space-100);
  width: auto;
  padding-block-end: var(--dimension-space-100);
  padding-inline-end: var(--dimension-space-100);
  border-inline-end: none;
}

:host(.card-overview--stacked) .card-overview__score-label-row {
  grid-row: 1;
  grid-column: 1 / -1;
  min-height: var(--ds-control-height);
}

:host(.card-overview--stacked) .card-overview__score-band,
:host(.card-overview--stacked) .card-overview__score-figure {
  grid-row: 2;
  margin-block-start: 0;
}

:host(.card-overview--stacked) .card-overview__score-figure {
  grid-column: 1;
  align-self: baseline;
  gap: var(--dimension-space-100);
}

:host(.card-overview--stacked) .card-overview__score-band {
  grid-column: 2;
  align-self: baseline;
  display: none;
}

:host(.card-overview--stacked) .card-overview__header {
  display: grid;
  grid-row: 1;
  grid-column: 2;
  grid-template-rows: auto auto;
  align-content: start;
  gap: 0;
  padding: 0;
  border-block-end: none;
}

:host(.card-overview--stacked) .card-overview__filter {
  grid-row: 1;
  grid-column: 1;
  align-self: start;
  justify-self: end;
  padding: var(--dimension-space-100) var(--dimension-space-100) 0 0;
}

:host(.card-overview--stacked) .card-overview__period {
  grid-row: 2;
  grid-column: 1;
  flex-direction: column;
  align-items: flex-end;
  justify-self: stretch;
  gap: 0;
  min-height: 0;
  padding-block: var(--dimension-space-150) var(--dimension-space-100);
  padding-inline: var(--dimension-space-100) var(--dimension-space-200);
  overflow: visible;
  text-align: end;
  white-space: nowrap;
}

:host(.card-overview--stacked) .card-overview__body {
  grid-row: 2;
  grid-column: 1;
}

:host(.card-overview--stacked) .card-overview__metrics {
  grid-template-columns: minmax(0, 1fr);
}

/* ── Compact presentation ───────────────────────────────────────────────── */

/*
 * Matches the shared 48px bar contract: one 32px control row with 8px above
 * and below. The score remains a distinct leading cell, while reporting copy
 * absorbs the available width and the application-owned control never shrinks.
 */
:host(.card-overview--compact) {
  height: var(--dimension-size-600);
  min-height: var(--dimension-size-600);
}

:host(.card-overview--compact) .card-overview__surface {
  height: 100%;
}

:host(.card-overview--compact) .card-overview__layout,
:host(.card-overview--compact) .card-overview__summary {
  display: flex;
  width: 100%;
  height: 100%;
  min-width: 0;
}

:host(.card-overview--compact) .card-overview__score {
  display: flex;
  flex: 0 0 auto;
  flex-direction: row;
  align-items: center;
  gap: var(--dimension-space-100);
  width: auto;
  height: 100%;
  min-width: 0;
  padding: var(--dimension-space-100) var(--dimension-space-200);
  border-inline-end: var(--ds-card-overview-divider);
  box-sizing: border-box;
}

:host(.card-overview--compact) .card-overview__score-label-row {
  display: contents;
  min-height: 0;
}

:host(.card-overview--compact) .card-overview__score-label,
:host(.card-overview--compact) .card-overview__score-figure,
:host(.card-overview--compact) .card-overview__trend {
  flex: 0 0 auto;
}

:host(.card-overview--compact) .card-overview__score-figure {
  display: flex;
  align-self: center;
  align-items: baseline;
  gap: var(--dimension-space-050);
  margin-block-start: 0;
}

:host(.card-overview--compact) .card-overview__score-band {
  display: none;
}

:host(.card-overview--compact) .card-overview__header {
  display: flex;
  flex: 1 1 auto;
  grid-row: auto;
  grid-column: auto;
  align-items: center;
  gap: var(--dimension-space-100);
  height: 100%;
  min-width: 0;
  padding: var(--dimension-space-100);
  border-block-end: none;
  box-sizing: border-box;
}

:host(.card-overview--compact) .card-overview__period {
  display: flex;
  flex: 1 1 auto;
  flex-direction: row;
  align-items: center;
  gap: var(--dimension-space-050);
  min-width: 0;
  min-height: var(--ds-control-height);
  padding-inline: var(--ds-control-padding-inline);
  overflow: hidden;
  text-align: start;
  white-space: nowrap;
}

:host(.card-overview--compact) .card-overview__period-current,
:host(.card-overview--compact) .card-overview__period-comparison {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

:host(.card-overview--compact) .card-overview__period-current {
  flex: 0 1 auto;
}

:host(.card-overview--compact) .card-overview__period-comparison {
  flex: 1 1 auto;
}

:host(.card-overview--compact) .card-overview__filter {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  padding: 0;
}

import { Component, Element, Event, EventEmitter, h, Host, Prop, State } from '@stencil/core';
import { resolveCssLengthPx, TOKEN_DEFAULTS } from '../../utils';
import type { TextColor, TextVariant } from '../Text/text-types';
import type { MetricTrend } from '../../utils/metric-change';
import type {
  CardOverviewLayout,
  CardOverviewVariant,
  OverviewMetric,
  OverviewScore,
} from './card-overview-types';
import {
  findNextOverviewMetricIndex,
  resolveCardOverviewCollapseGeometry,
  resolveOverviewRovingIndex,
} from './card-overview-controller';

/** Metric cells below this width drop a grid column rather than compress further. */
const DEFAULT_METRIC_MIN_WIDTH = 'var(--dimension-menu-width-xs)';

/** Skeleton cells rendered while loading with no metrics supplied yet. */
const LOADING_PLACEHOLDER_COUNT = 4;

/** Maximum number of comparable measures the summary bar presents at once. */
const MAX_METRIC_COUNT = 6;

const TREND_COLORS: Record<MetricTrend['tone'], TextColor> = {
  positive: 'var(--color-inverted-foreground-positive)',
  negative: 'var(--color-inverted-foreground-negative)',
  neutral: 'var(--color-inverted-foreground-secondary)',
};

const INVERTED_PRIMARY: TextColor = 'var(--color-inverted-foreground-primary)';
const INVERTED_SECONDARY: TextColor = 'var(--color-inverted-foreground-secondary)';

@Component({
  tag: 'ds-card-overview',
  styleUrl: 'CardOverview.css',
  scoped: true,
})
export class CardOverview {
  @Element() el!: HTMLElement;

  /** Full summary card, or the condensed 48px summary bar. */
  @Prop() variant: CardOverviewVariant = 'default';

  /** Intrinsic responsive layout, or a page-owned single-column stack. */
  @Prop() layout: CardOverviewLayout = 'auto';

  /** Leading summary block. Omit to render the bar without a headline figure. */
  @Prop() score: OverviewScore | undefined;

  /** Current reporting period, for example `Jun 29, 2026 – Jul 26, 2026`. */
  @Prop() periodLabel: string = '';

  /** Comparison caption, for example `vs Previous period`. */
  @Prop() comparisonLabel: string = '';

  /** Measures rendered in the responsive grid. Only the first six are shown. */
  @Prop() metrics: OverviewMetric[] = [];

  /**
   * Width a metric cell may shrink to before the grid drops a column. The grid
   * reflows and then stacks from this alone, so no measurement is required.
   */
  @Prop() metricMinWidth: string = DEFAULT_METRIC_MIN_WIDTH;

  /** Replace the score and metrics with skeletons while data resolves. */
  @Prop() isLoading: boolean = false;

  /** Message shown in place of the score when its figure cannot be resolved. */
  @Prop() scoreErrorMessage: string | undefined;

  /** Accessible name for the region. */
  @Prop() overviewLabel: string = 'Overview';

  /**
   * Page-controlled visual collapse from the full card (`0`) toward its 48px
   * compact handoff height (`1`). The component preserves its expanded flow
   * height, keeps elevation on the shrinking surface, and clips translated
   * content internally. The page still owns sticky positioning and the final
   * swap to `variant="compact"`.
   */
  @Prop() scrollCollapseProgress: number = 0;

  /** Emitted when a metric that is not inactive is activated. */
  @Event() dsMetricSelect!: EventEmitter<OverviewMetric>;

  /** Roving tab stop across selectable metrics. */
  @State() private focusedMetricIndex: number = 0;
  @State() private expandedHeight: number = 0;

  private layoutEl?: HTMLElement;
  private layoutResizeObserver: ResizeObserver | null = null;

  componentDidLoad() {
    this.observeLayout();
  }

  componentDidRender() {
    // Re-bind after HMR when DidLoad's observer was dropped.
    if (!this.layoutResizeObserver) this.observeLayout();
  }

  disconnectedCallback() {
    this.layoutResizeObserver?.disconnect();
    this.layoutResizeObserver = null;
  }

  private get hasScore(): boolean {
    return this.score !== undefined || this.scoreErrorMessage !== undefined || this.isLoading;
  }

  private get visibleMetrics(): OverviewMetric[] {
    return this.metrics.slice(0, MAX_METRIC_COUNT);
  }

  private get resolvedScrollCollapseProgress(): number {
    if (this.variant === 'compact' || !Number.isFinite(this.scrollCollapseProgress)) return 0;
    return Math.min(1, Math.max(0, this.scrollCollapseProgress));
  }

  private get scrollCollapseGeometry() {
    const compactHeight = resolveCssLengthPx(TOKEN_DEFAULTS.size600, 48);
    return resolveCardOverviewCollapseGeometry({
      variant: this.variant,
      progress: this.resolvedScrollCollapseProgress,
      expandedHeight: this.expandedHeight,
      compactHeight,
    });
  }

  private observeLayout() {
    const layout = this.layoutEl;
    if (!layout) return;

    const updateHeight = (height: number) => {
      if (height > 0 && Math.abs(height - this.expandedHeight) >= 0.5) {
        this.expandedHeight = height;
      }
    };

    updateHeight(layout.getBoundingClientRect().height);
    if (typeof ResizeObserver === 'undefined') return;

    this.layoutResizeObserver?.disconnect();
    this.layoutResizeObserver = new ResizeObserver(entries => {
      const height = entries[0]?.contentRect.height;
      if (height !== undefined) updateHeight(height);
    });
    this.layoutResizeObserver.observe(layout);
  }

  /** Index of the roving tab stop, skipping inactive metrics. */
  private get rovingIndex(): number {
    return resolveOverviewRovingIndex(this.visibleMetrics, this.focusedMetricIndex);
  }

  private selectMetric(metric: OverviewMetric, index: number) {
    if (metric.isInactive) return;
    this.focusedMetricIndex = index;
    this.dsMetricSelect.emit(metric);
  }

  /** Move the roving tab stop, wrapping and skipping inactive metrics. */
  private moveFocus(from: number, step: number) {
    const metrics = this.visibleMetrics;
    const next = findNextOverviewMetricIndex(metrics, from, step < 0 ? -1 : 1);
    if (next < 0) return;

    this.focusedMetricIndex = next;
    const cells = this.el.querySelectorAll<HTMLElement>('.card-overview__metric');
    cells[next]?.focus();
  }

  private handleMetricKeyDown = (event: KeyboardEvent, index: number) => {
    switch (event.key) {
      case 'ArrowRight':
      case 'ArrowDown':
        event.preventDefault();
        this.moveFocus(index, 1);
        break;
      case 'ArrowLeft':
      case 'ArrowUp':
        event.preventDefault();
        this.moveFocus(index, -1);
        break;
      default:
        break;
    }
  };

  /**
   * A skeleton bar matching the type metrics of the text it stands in for, so the
   * loading state holds the same shape and rhythm as the resolved content.
   *
   * `background` is always passed so the base and shimmer follow the card's
   * inverted surface in both themes.
   */
  private bar(textVariant: TextVariant, width: string, className?: string) {
    return (
      <ds-skeleton
        class={className}
        variant="text"
        textVariant={textVariant}
        width={width}
        background="inverted"
      />
    );
  }

  /**
   * Arrow and change in one text node.
   *
   * The arrow is a typeface glyph rather than an icon so it inherits the exact
   * size, weight, and baseline of the value beside it; an icon would need its
   * own size scale and would drift whenever the type scale changed.
   *
   * Tone is supplied by the caller and never inferred here.
   */
  private renderTrend(trend: MetricTrend | undefined, variant: TextVariant, emphasis = false) {
    if (!trend) return null;
    return (
      <ds-text
        as="span"
        class={{
          'card-overview__trend': true,
          [`card-overview__trend--${trend.tone}`]: true,
        }}
        variant={variant}
        emphasis={emphasis}
        color={TREND_COLORS[trend.tone]}
        fontFeature="tabular-nums"
      >
        {trend.direction === 'up' ? '↑' : '↓'} {trend.value}
      </ds-text>
    );
  }

  private renderScore(compact: boolean) {
    if (this.isLoading) {
      if (compact) {
        return (
          <div class="card-overview__score ds-control--md" part="score">
            {this.bar('text-body-medium', '40px', 'card-overview__score-label')}
            <div class="card-overview__score-figure">
              {this.bar('text-body-medium', '24px')}
              {this.bar('text-body-medium', '32px')}
            </div>
          </div>
        );
      }

      return (
        <div class="card-overview__score ds-control--md" part="score">
          {/*
           * The label row is kept but left empty. It carries the control-height
           * box that aligns the score block with the period control, so dropping
           * it would shift the whole block up; a bar inside it would collide with
           * the figure, which sits under the label by design.
           */}
          <div class="card-overview__score-label-row" />
          <div class="card-overview__score-figure">
            {this.bar('text-display-medium', '56px')}
            {this.bar('text-body-small', '24px', 'card-overview__skeleton-baseline')}
          </div>
          {/*
           * Class goes on the skeleton itself, matching the resolved band. In a
           * wrapper the bar picks up inline leading and drops below the resolved
           * band position.
           */}
          {this.bar(
            'text-caption',
            '80px',
            'card-overview__score-band card-overview__score-band--loading'
          )}
        </div>
      );
    }

    if (this.scoreErrorMessage) {
      return (
        <div class="card-overview__score card-overview__score--error" part="score" role="alert">
          <ds-icon name="CircleExclamation" size="sm" color="inherit" aria-hidden="true" />
          <ds-text as="span" variant="text-body-medium" color="inherit">
            {this.scoreErrorMessage}
          </ds-text>
        </div>
      );
    }

    const score = this.score;
    if (!score) return null;

    return (
      <div class="card-overview__score card-overview__score--resolved ds-control--md" part="score">
        {/* The row owns cross-layout baseline geometry and becomes display: contents in compact mode. */}
        {/* eslint-disable-next-line local/prefer-direct-ds-text */}
        <div class="card-overview__score-label-row">
          <ds-text
            as="span"
            class="card-overview__score-label"
            variant="text-body-medium"
            emphasis={!compact}
            color={INVERTED_SECONDARY}
          >
            {score.label}
          </ds-text>
        </div>
        <div class="card-overview__score-figure">
          <ds-text
            as="span"
            class="card-overview__score-value"
            variant={compact ? 'text-body-medium' : 'text-display-medium'}
            emphasis
            color={INVERTED_PRIMARY}
            fontFeature="tabular-nums"
          >
            {score.value}
          </ds-text>
          {this.renderTrend(
            score.trend,
            compact ? 'text-body-medium' : 'text-body-small',
            !compact
          )}
        </div>
        {score.band && !compact && (
          <ds-text
            as="span"
            class="card-overview__score-band"
            variant="text-caption"
            color={INVERTED_SECONDARY}
          >
            {score.band}
          </ds-text>
        )}
      </div>
    );
  }

  private renderMetric(metric: OverviewMetric, index: number) {
    const selectable = !metric.isInactive;
    const label = (
      <ds-text
        as="span"
        class="card-overview__metric-label"
        variant="text-body-small"
        color={INVERTED_SECONDARY}
      >
        {metric.label}
      </ds-text>
    );

    return (
      <div
        class={{
          'card-overview__metric': true,
          'card-overview__metric--inactive': !selectable,
          // Selection targets get the shared wash; press scaling is not used here
          // so the grid keeps its columns aligned. See docs/control-press-policy.md.
          'ds-interaction-fill': selectable,
          'ds-interaction-fill--on-inverted': selectable,
          'ds-focus-ring-inset': selectable,
        }}
        part="metric"
        role={selectable ? 'button' : undefined}
        tabIndex={selectable && index === this.rovingIndex ? 0 : -1}
        onClick={() => this.selectMetric(metric, index)}
        onKeyDown={event => this.handleMetricKeyDown(event, index)}
        onFocusin={() => {
          if (selectable) this.focusedMetricIndex = index;
        }}
      >
        {metric.labelTooltip ? (
          <ds-tooltip label={metric.labelTooltip} side="top" size="sm">
            {label}
          </ds-tooltip>
        ) : (
          label
        )}
        <div class="card-overview__metric-figure">
          <ds-text
            as="span"
            class="card-overview__metric-value"
            variant="text-body-medium"
            color={INVERTED_PRIMARY}
            fontFeature="tabular-nums"
          >
            {metric.value}
          </ds-text>
          {this.renderTrend(metric.trend, 'text-body-medium')}
        </div>
      </div>
    );
  }

  private renderMetrics() {
    if (this.isLoading && this.metrics.length === 0) {
      return Array.from({ length: LOADING_PLACEHOLDER_COUNT }, (_, index) => (
        <div class="card-overview__metric" key={`loading-${index}`}>
          {this.bar('text-body-small', '70%', 'card-overview__metric-label')}
          <div class="card-overview__metric-figure">
            {this.bar('text-body-medium', '36px')}
            {/* text-body-medium, matching renderTrend for a metric — a smaller
             * variant here leaves the trend bar short of the value beside it. */}
            {this.bar('text-body-medium', '40px')}
          </div>
        </div>
      ));
    }

    return this.visibleMetrics.map((metric, index) => this.renderMetric(metric, index));
  }

  render() {
    const hasHeader = Boolean(this.periodLabel || this.comparisonLabel);
    const compact = this.variant === 'compact';
    const collapse = this.scrollCollapseGeometry;

    return (
      <Host
        class={{
          'card-overview': true,
          'card-overview--has-score': this.hasScore,
          'card-overview--compact': compact,
          'card-overview--stacked': !compact && this.layout === 'stacked',
          'card-overview--scroll-collapsing': collapse.active,
        }}
        role="region"
        aria-label={this.overviewLabel}
        aria-busy={this.isLoading ? 'true' : undefined}
        style={{
          '--ds-card-overview-metric-min': this.metricMinWidth,
          '--ds-card-overview-expanded-height': collapse.active
            ? `${collapse.expandedHeight}px`
            : undefined,
          '--ds-card-overview-visible-height': collapse.active
            ? `${collapse.visibleHeight}px`
            : undefined,
          '--ds-card-overview-content-offset': collapse.active
            ? `${collapse.offset}px`
            : undefined,
        }}
      >
        <div
          class={{
            'card-overview__surface': true,
            // Split shadow and inset highlight, so the opaque surface cannot cover
            // the highlight the way a combined elevation shadow would.
            'ds-control-elevation': true,
            'ds-control-elevation--sm': !compact,
            'ds-control-elevation--floating': compact,
          }}
        >
          <div class="card-overview__clip">
            <div
              ref={element => {
                this.layoutEl = (element as HTMLElement) ?? undefined;
              }}
              class={{
                'card-overview__layout': true,
                'card-overview__layout--has-score': this.hasScore,
              }}
            >
              <div class="card-overview__summary">
                {this.hasScore && this.renderScore(compact)}

                {/* `ds-control--md` supplies the 32px height and the label inset below. */}
                <div
                  class={{
                    'card-overview__header': true,
                    'card-overview__header--has-score': this.hasScore,
                    'ds-control--md': true,
                  }}
                >
                  {this.isLoading ? (
                    <div class="card-overview__period ds-control-label-box">
                      {this.bar('text-body-medium', '184px')}
                      {this.bar('text-body-medium', '248px')}
                    </div>
                  ) : (
                    hasHeader && (
                      <div class="card-overview__period ds-control-label-box">
                        {this.periodLabel && (
                          <ds-text
                            as="span"
                            class="card-overview__period-current ds-control-label-box"
                            variant="text-body-medium"
                            emphasis
                            color={INVERTED_PRIMARY}
                          >
                            {this.periodLabel}
                          </ds-text>
                        )}
                        {this.comparisonLabel && (
                          <ds-text
                            as="span"
                            class="card-overview__period-comparison ds-control-label-box"
                            variant="text-body-medium"
                            color={INVERTED_SECONDARY}
                          >
                            {this.comparisonLabel}
                          </ds-text>
                        )}
                      </div>
                    )
                  )}
                  <div class="card-overview__filter">
                    {/*
                      Period control is application owned: it varies by product surface.
                      While loading it is stood in for by a control-shaped skeleton so the
                      header keeps its resolved proportions.
                    */}
                    {this.isLoading ? (
                      <ds-skeleton
                        variant="control"
                        controlSize="md"
                        width="128px"
                        background="inverted"
                      />
                    ) : (
                      <slot name="filter" />
                    )}
                  </div>
                </div>
              </div>

              {!compact && (
                <div
                  class={{
                    'card-overview__body': true,
                    'card-overview__body--has-score': this.hasScore,
                  }}
                >
                  <div class="card-overview__metrics" part="metrics">
                    {this.renderMetrics()}
                  </div>

                  <slot name="footer" />
                </div>
              )}
            </div>
          </div>
        </div>
      </Host>
    );
  }
}

import type { CardOverviewVariant, OverviewMetric } from './card-overview-types';

export interface CardOverviewCollapseGeometry {
  active: boolean;
  expandedHeight: number;
  offset: number;
  visibleHeight: number;
}

export function resolveCardOverviewCollapseGeometry(options: {
  variant: CardOverviewVariant;
  progress: number;
  expandedHeight: number;
  compactHeight: number;
}): CardOverviewCollapseGeometry {
  const compactHeight = Math.max(0, options.compactHeight);
  const expandedHeight = Math.max(options.expandedHeight, compactHeight);
  const progress =
    options.variant === 'compact' || !Number.isFinite(options.progress)
      ? 0
      : Math.min(1, Math.max(0, options.progress));
  const distance = Math.max(0, expandedHeight - compactHeight);
  const offset = distance * progress;

  return {
    active: progress > 0 && distance > 0,
    expandedHeight,
    offset,
    visibleHeight: expandedHeight - offset,
  };
}

export function resolveOverviewRovingIndex(
  metrics: readonly OverviewMetric[],
  focusedIndex: number
): number {
  const first = metrics.findIndex(metric => !metric.isInactive);
  if (first < 0) return -1;
  return metrics[focusedIndex] && !metrics[focusedIndex].isInactive
    ? focusedIndex
    : first;
}

export function findNextOverviewMetricIndex(
  metrics: readonly OverviewMetric[],
  from: number,
  step: -1 | 1
): number {
  for (let offset = 1; offset <= metrics.length; offset += 1) {
    const next = (((from + step * offset) % metrics.length) + metrics.length) % metrics.length;
    if (!metrics[next]?.isInactive) return next;
  }
  return -1;
}

import type { MetricTrend } from '../../utils/metric-change';

export type CardOverviewVariant = 'default' | 'compact';
export type CardOverviewLayout = 'auto' | 'stacked';

/**
 * Leading summary block — the headline figure the rest of the bar contextualises.
 *
 * Derive `trend` with `resolveMetricTrend` so whether a rise reads well stays a
 * product decision rather than a design-system one.
 */
export interface OverviewScore {
  /** Category above the figure, for example `Safety score`. */
  label: string;
  /** Display-ready headline figure. */
  value: string | number;
  /** Change against the comparison period. Omit when there is nothing to report. */
  trend?: MetricTrend;
  /** Qualitative band beneath the figure, for example `Good (67–83)`. */
  band?: string;
}

/** One measure in the overview grid. */
export interface OverviewMetric {
  /** Stable identity for keyed rendering and selection events. */
  id: string;
  label: string;
  /** Display-ready value; format compactly before passing it in. */
  value: string | number;
  /** Change against the comparison period. Omit when there is nothing to report. */
  trend?: MetricTrend;
  /** Present the measure without making it selectable. */
  isInactive?: boolean;
  /** Supplementary explanation for the label. */
  labelTooltip?: string;
}
